-- =====================================================================
-- Stage weights for the batch 4 root causes (industries 16-20).
--
-- WHY. confidence.py reads root_cause_weights.stage_weight as a four-level
-- relevance scale and normalises it onto 0..1. stage_probability carries 20%
-- of root-cause ranking (WEIGHT_STAGE_PROBABILITY = 0.20), so a cause with no
-- row for the founder's stage has that factor recorded unavailable and ranks
-- on the remaining 80%. New content with no rows competes at a standing
-- disadvantage against the original catalogue.
--
-- Idempotent, no hardcoded ids: the cause is resolved by code, and every
-- insert is ON CONFLICT DO NOTHING on (root_cause_id, stage_id).
-- =====================================================================
BEGIN;
select setval(pg_get_serial_sequence('root_cause_weights','weight_id'), greatest((select coalesce(max(weight_id),0) from root_cause_weights), 1));

-- HRT

-- TRD

-- MFG

-- SAS

-- LGL

do $$
declare short int; total int;
begin
  select count(*) into short from (
    select rc.root_cause_id from root_causes rc
      left join root_cause_weights w on w.root_cause_id = rc.root_cause_id
     where rc.root_cause_code ~ '^RC-(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]-[0-9]$'
     group by rc.root_cause_id having count(w.weight_id) <> 8) x;
  select count(*) into total from root_causes
   where root_cause_code ~ '^RC-(HRT|TRD|MFG|SAS|LGL)-3[0-9][0-9]-[0-9]$';
  if total <> 135 then
    raise exception 'expected 135 batch 4 root causes, found % -- load batch4_industries_16to20.sql first', total;
  end if;
  if short > 0 then
    raise exception 'stage weights incomplete: % batch 4 root causes do not have 8 rows', short;
  end if;
  raise notice 'stage weights ok: all 135 batch 4 root causes carry all 8 stages';
end $$;
COMMIT;
